g=[[9,9,9,9,4,9,4,4,4,9,4,4,4,9,4,4,9,9,4],[9,9,9,9,4,9,9,9,9,9,9,9,9,9,9,9,9,9,4],[9]*19,[9,9,9,9,4,9,4,4,4,4,9,9,4,4,4,4,4,4,4],[9,9,9,9,4,9,9,9,9,9,9,9,9,9,9,9,9,9,9],[9,9,9,9,4,9,9,9,9,9,9,9,9,9,9,9,9,9,4],[9,9,9,9,4,4,9,4,9,4,4,9,9,4,9,4,9,4,4],[9]*19,[9]*19,[9]*19]
base=[r[:] for r in g]
for r,row in enumerate(g):
 ix=[c for c,x in enumerate(row) if x==4]
 for a,b in zip(ix,ix[1:]):
  for c in range(a+1,b): base[r][c]=2
for c in range(19):
 ix=[r for r in range(10) if g[r][c]==4]
 for a,b in zip(ix,ix[1:]):
  for r in range(a+1,b): base[r][c]=2
# identify pairs with min delta=1 and path algorithm
pts=[(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x==4]
extra=set()
for i,(r,c) in enumerate(pts):
 for r2,c2 in pts[i+1:]:
  dr,dc=r2-r,c2-c
  if abs(dc)==1 and abs(dr)>1:
   # fill along vertical column of first point to row2, including endpoint row
   for rr in range(r+1,r2+1):
    if g[rr][c]==9: extra.add((rr,c))
  if abs(dr)==1 and abs(dc)>1:
   # fill along row of lower endpoint, from its c to other c
   rr=r2
   for cc in range(min(c,c2),max(c,c2)+1):
    if g[rr][cc]==9: extra.add((rr,cc))
print('extras',sorted(extra))
